<h1><?= te('Promotions and transfers') ?></h1><p class="sub"><?= te('Approved changes retain assignment history. A transfer starts a new assignment with its own onboarding and logistics.') ?></p><form class="card" method="post"><?= csrf_field() ?><label><?= te('Worker') ?></label><select name="placement_id"><?php foreach($crew as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['full_name']) ?></option><?php endforeach; ?></select><label><?= te('Change') ?></label><select name="kind"><option value="promotion"><?= te('Promotion / title change') ?></option><option value="transfer"><?= te('Project transfer') ?></option></select><label><?= te('New title / trade') ?></label><input name="new_trade" maxlength="190"><label><?= te('Target project (transfer)') ?></label><select name="target_job_id"><option value=""><?= te('Select project') ?></option><?php foreach($jobs as $j): ?><option value="<?= (int)$j['id'] ?>"><?= e($j['title']) ?></option><?php endforeach; ?></select><label><?= te('Effective date · today or earlier') ?></label><input type="date" name="effective_on" required max="<?= e(date('Y-m-d')) ?>" value="<?= e(date('Y-m-d')) ?>"><label><?= te('Reason') ?></label><textarea name="reason" required></textarea><button class="btn"><?= te('Approve and apply change') ?></button></form><div class="card"><h2><?= te('Change history') ?></h2><?php foreach($changes as $c): ?><p><?= e($c['full_name'].' · '.$c['kind'].' · '.$c['previous_trade'].' → '.$c['new_trade'].' · '.$c['effective_on']) ?></p><?php endforeach; ?></div>